old text-[#2457e6]" :href="selectedProduct.source" target="_blank" rel="noreferrer">{{ selectedProduct.sourceLabel }} <ExternalLink :size="15" /></a></div><div class="mt-14 flex flex-wrap gap-3"><button type="button" class="inline-flex h-11 items-center gap-2 rounded-lg bg-[#2457e6] px-5 text-sm font-semibold text-white" @click="chatOpen = true">询问 AI 助手 <ArrowRight :size="15" /></button><RouterLink to="/product/support" class="inline-flex h-11 items-center gap-2 rounded-lg border border-[#dfe6df] bg-white px-5 text-sm font-semibold text-[#40504a]">服务支持</RouterLink></div></div></div></main>
